#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long long a = strtoll(argv[1], &end1, 10);
    long long b = strtoll(argv[2], &end2, 10);
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (b == 0) {
        puts("ERROR");
        return 0;
    }
    if (llabs(a) > 100000LL || llabs(b) > 100000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // Ensure denominator positive for standard continued fraction
    if (b < 0) {
        a = -a;
        b = -b;
    }
    long long terms[200];
    int count = 0;
    while (b != 0) {
        long long q = a / b;
        long long r = a % b;
        // Adjust for floor division when remainder is negative
        if (r < 0) {
            if (b > 0) {
                q -= 1;
                r += b;
            } else {
                q += 1;
                r -= b;
            }
        }
        if (count >= 200) { // too many terms
            puts("ERROR");
            return 0;
        }
        terms[count++] = q;
        a = b;
        b = r;
    }
    // Output in [a0; a1, a2, ...] format
    putchar('[');
    if (count > 0) {
        printf("%lld", terms[0]);
        if (count > 1) {
            printf("; ");
            for (int i = 1; i < count; ++i) {
                printf("%lld", terms[i]);
                if (i + 1 < count) {
                    printf(", ");
                }
            }
        }
    }
    putchar(']');
    putchar('\n');
    return 0;
}
